mapper.select:
select e.alert_id as alertId, e.rule_id as ruleId, e.inventory_id as inventoryId, e.warehouse_id as warehouseId, w.warehouse_name as warehouseName, e.product_id as productId, p.product_code as productCode, p.product_name as productName, e.alert_type as alertType, e.alert_status as alertStatus, e.snapshot_total_quantity as snapshotTotalQuantity, e.snapshot_available_quantity as snapshotAvailableQuantity, e.threshold_type as thresholdType, e.threshold_value as thresholdValue, e.alert_message as alertMessage, e.first_triggered_time as firstTriggeredTime, e.last_triggered_time as lastTriggeredTime, e.acknowledged_time as acknowledgedTime, e.resolved_time as resolvedTime from ry_business.ry_rental_inventory_alert_event e left join ry_business.ry_rental_warehouse w on w.tenant_id = e.tenant_id and w.member_id = e.member_id and w.warehouse_id = e.warehouse_id and w.is_delete = 0 left join ry_business.ry_rental_product p on p.tenant_id = e.tenant_id and p.member_id = e.member_id and p.product_id = e.product_id and p.is_delete = 0 where e.tenant_id = #{tenantId} and e.member_id = #{memberId} and e.is_delete = 0 and e.alert_status = #{alertStatus} and e.warehouse_id = #{warehouseId}
and e.warehouse_id in
#{allowedWarehouseId}
and 1 = 0
order by e.alert_status, e.last_triggered_time desc, e.alert_id desc
